// Gate name mapping
const GATE_NAMES = {
    'stor_cnc': 'Stor CNC',
    'lille_cnc': 'Lille CNC',
    'rundsav': 'Rundsav',
    'disponibel_1': 'Disponibel 1',
    'disponibel_2': 'Disponibel 2',
    'rondelsliber': 'Rondelsliber',
    'baandsliber': 'Båndsliber'
};

// Get gate ID from topic
const parts = msg.topic.split('/');
const gateId = parts[2];
const isActive = msg.payload === '1';

// Store in flow context
let machines = flow.get('activeMachines') || {};
machines[gateId] = isActive;
flow.set('activeMachines', machines);

// Store name mapping
flow.set('gateNames', GATE_NAMES);

return null;

const isActive = msg.payload === '1';
const prevState = flow.get('vacuumState');

// Skip if no change (including first retained message)
if (prevState === isActive) {
    return null;
}
flow.set('vacuumState', isActive);

// Skip the very first message (retained) to avoid false log entry
if (prevState === undefined) {
    return null;
}

// Get active machines
const machines = flow.get('activeMachines') || {};
const GATE_NAMES = flow.get('gateNames') || {};

const activeMachines = [];
for (const [gateId, active] of Object.entries(machines)) {
    if (active) {
        activeMachines.push(GATE_NAMES[gateId] || gateId);
    }
}

const entry = {
    timestamp: new Date().toISOString(),
    vacuumActive: isActive,
    activeMachines: activeMachines
};

msg.payload = JSON.stringify(entry) + '\n';
return msg;

const data = msg.payload || '';
const lines = data.trim().split('\n').filter(l => l.length > 0);
const entries = lines.map(line => {
    try { return JSON.parse(line); }
    catch(e) { return null; }
}).filter(e => e !== null);

// Return newest first
entries.reverse();
const limit = parseInt((msg.req.query && msg.req.query.limit) || 200);
msg.payload = entries.slice(0, limit);
msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
};
return msg;
